G("ley-de-snell-y-refraccion-de-la-luz", "Ley de Snell y refracción de la luz",
  "Ley de Snell y Refracción de la Luz: Fórmula, Ángulo Crítico y Ejemplos | Calculadora Científica",
  "Qué es la refracción de la luz, la ley de Snell (n₁·sen θ₁ = n₂·sen θ₂), los índices de refracción de materiales comunes, el ángulo crítico, la reflexión total interna y ejemplos resueltos.",
  "Ley de Snell, índices de refracción, ángulo crítico y reflexión total, con ejemplos.",
  "Ley de Snell y refracción de la luz",
  "Un lápiz en un vaso de agua parece quebrado, y la luz de una pileta nunca llega al fondo por donde esperaríamos. Es la refracción: la luz cambia de dirección al pasar de un medio a otro, y la ley de Snell dice cuánto.",
  "n₁·sen θ₁ = n₂·sen θ₂ · n = c/v · ángulo crítico: θc = arcsen(n₂/n₁) si n₁ > n₂.",
  ("/calculadoras/fisica/calculadora-de-ley-de-snell/", "Abrir calculadora"),
  [g_h2("1. La ley de Snell"),
   g_formula("n₁ · sen θ₁ = n₂ · sen θ₂"),
   g_p("Los ángulos θ₁ (de incidencia) y θ₂ (de refracción) se miden respecto de la normal, la recta perpendicular a la superficie, no respecto de la superficie. Al entrar a un medio de mayor índice de refracción el rayo se acerca a la normal; al pasar a uno de menor índice, se aleja."),
   g_h2("2. El índice de refracción"),
   g_formula("n = c / v"),
   g_p("Es el cociente entre la velocidad de la luz en el vacío (c ≈ 299.792 km/s) y su velocidad en el medio. Siempre es mayor o igual que 1."),
   g_table(["Medio", "n", "Velocidad de la luz"], [["Vacío", "1", "299.792 km/s"], ["Aire", "1,0003", "casi igual"], ["Hielo", "1,31", "228.800 km/s"], ["Agua", "1,333", "225.000 km/s"], ["Aceite", "1,47", "204.000 km/s"], ["Vidrio común", "1,52", "197.000 km/s"], ["Diamante", "2,417", "124.000 km/s"]]),
   g_h2("3. Ejemplo: de aire a agua"),
   g_steps(["Un rayo incide a 30° desde el aire (n₁ = 1,0003) sobre agua (n₂ = 1,333)", "sen θ₂ = 1,0003 · sen 30° / 1,333 = 0,3752", "θ₂ = arcsen(0,3752) ≈ 22,0°"]),
   g_p("El rayo se acerca a la normal porque el agua tiene mayor índice que el aire."),
   g_h2("4. Cómo hallar el índice de un material"),
   g_steps(["Un rayo entra desde el aire a 45° y se refracta a 28,1°", "n₂ = n₁ · sen θ₁ / sen θ₂ = 1 · 0,7071 / 0,4710", "n₂ ≈ 1,50 (un vidrio)"]),
   g_h2("5. Ángulo crítico y reflexión total interna"),
   g_p("Al pasar a un medio de menor índice, el rayo se aleja de la normal. Existe un ángulo de incidencia, el crítico, para el que el rayo refractado sale rasante (θ₂ = 90°). Más allá de ese ángulo no hay refracción: la luz se refleja por completo."),
   g_formula("θc = arcsen(n₂ / n₁) &nbsp;&nbsp; (solo si n₁ &gt; n₂)"),
   g_table(["Paso de…", "Ángulo crítico"], [["Agua a aire", "48,6°"], ["Vidrio (1,52) a aire", "41,1°"], ["Diamante a aire", "24,4°"]]),
   g_p("El ángulo crítico del diamante es muy chico, por eso la luz queda atrapada y rebota dentro de la piedra: de ahí su brillo. En la fibra óptica, la luz viaja por reflexión total interna a lo largo del cable."),
   g_h2("6. Profundidad aparente"),
   g_p("Visto desde arriba y en forma casi perpendicular, un objeto sumergido parece estar a menos profundidad: la profundidad aparente es la real multiplicada por n₂/n₁. Un pez a 1,2 m en el agua parece estar a 1,2 / 1,333 = 0,9 m."),
   g_h2("7. Errores comunes"),
   g_ul(["Medir los ángulos respecto de la superficie en lugar de la normal.", "Calcular el ángulo crítico cuando la luz pasa a un medio de mayor índice (no existe).", "Olvidar que, si n₁·sen θ₁ / n₂ supera 1, no hay solución para θ₂: es reflexión total.", "Calcular con la calculadora en radianes en lugar de grados."])],
  [("¿Qué dice la ley de Snell?", "Que n₁·sen θ₁ = n₂·sen θ₂: relaciona los ángulos con la normal en ambos medios."),
   ("¿Qué es el ángulo crítico?", "El ángulo de incidencia a partir del cual hay reflexión total interna. De agua a aire, unos 48,6°."),
   ("¿Por qué un lápiz parece quebrado en el agua?", "Porque la luz se refracta al pasar del agua al aire y llega a tus ojos desde una dirección distinta."),
   ("¿Qué es el índice de refracción?", "n = c/v: cuántas veces más lenta es la luz en el medio que en el vacío.")],
  [("/calculadoras/fisica/calculadora-de-ley-de-snell/", "Calculadora de la ley de Snell"), ("/guias/teorema-del-seno-y-del-coseno/", "Guía: teorema del seno y del coseno"), ("/guias/grados-y-radianes/", "Guía: grados y radianes")])

