G("media-aritmetica-geometrica-y-armonica", "Media aritmética, geométrica y armónica",
  "Media Aritmética, Geométrica y Armónica: Fórmulas, Diferencias y Ejemplos | Calculadora Científica",
  "Cómo calcular la media aritmética, geométrica, armónica y cuadrática, cuándo usar cada una (crecimiento, velocidades, precios), la desigualdad entre ellas y ejemplos resueltos.",
  "Las cuatro medias, cuándo usar cada una y ejemplos resueltos.",
  "Media aritmética, geométrica y armónica",
  "\"Promedio\" no siempre significa sumar y dividir. Según lo que se quiera promediar (valores, tasas de crecimiento o velocidades), la media correcta es otra, y elegir mal da resultados engañosos.",
  "AM = Σx/n · GM = ⁿ√(Πx) · HM = n/Σ(1/x) · QM = √(Σx²/n) · HM ≤ GM ≤ AM ≤ QM.",
  ("/calculadoras/estadistica/calculadora-de-medias/", "Abrir calculadora"),
  [g_h2("1. Media aritmética"),
   g_formula("AM = (x₁ + x₂ + … + xₙ) / n"),
   g_p("Es el promedio de todos los días: se suman los valores y se divide por la cantidad. Es la adecuada para magnitudes que se suman (notas, alturas, temperaturas)."),
   g_h2("2. Media geométrica"),
   g_formula("GM = ⁿ√(x₁ · x₂ · … · xₙ)"),
   g_p("Se usa con factores que se multiplican: tasas de crecimiento, rendimientos, razones. Solo se define para números positivos."),
   g_steps(["Una inversión rinde +10 %, +20 % y −5 % en tres períodos", "factores: 1,10 · 1,20 · 0,95 = 1,254", "GM = 1,254^(1/3) ≈ 1,0784 → crecimiento promedio de 7,84 % por período"]),
   g_p("La media aritmética de los factores (1,0833, es decir 8,33 %) sobreestima el crecimiento real."),
   g_steps(["Una inversión sube 50 % y después baja 50 %", "la media aritmética de las variaciones es 0 %, pero 1,5 · 0,5 = 0,75: se perdió el 25 %", "GM = √0,75 ≈ 0,866 → −13,4 % por período"]),
   g_h2("3. Media armónica"),
   g_formula("HM = n / (1/x₁ + 1/x₂ + … + 1/xₙ)"),
   g_p("Es la correcta para promediar velocidades en tramos de igual distancia, o precios y rendimientos medidos \"por unidad\"."),
   g_steps(["Ida a 60 km/h y vuelta a 40 km/h (misma distancia)", "HM = 2 / (1/60 + 1/40) = 2 / 0,04167", "= 48 km/h (no 50 km/h)"]),
   g_steps(["Se compran dólares con $1.000 cada mes: el primer mes a $900 y el segundo a $1.100", "precio promedio de compra = 2 / (1/900 + 1/1.100)", "= $990 (menor que el promedio simple de $1.000)"]),
   g_h2("4. Media cuadrática"),
   g_formula("QM = √((x₁² + x₂² + … + xₙ²) / n)"),
   g_p("Se usa en física e ingeniería: el valor eficaz (RMS) de una señal eléctrica es una media cuadrática, y la desviación estándar es la media cuadrática de los desvíos."),
   g_h2("5. Cómo se relacionan"),
   g_p("Para números positivos siempre se cumple:"),
   g_formula("HM ≤ GM ≤ AM ≤ QM"),
   g_p("Las cuatro son iguales solo cuando todos los datos son iguales."),
   g_table(["Datos", "Armónica", "Geométrica", "Aritmética", "Cuadrática"], [["2 y 8", "3,20", "4,00", "5,00", "5,83"], ["1, 2, 3, 4", "1,92", "2,21", "2,50", "2,74"], ["5, 5, 5", "5,00", "5,00", "5,00", "5,00"]]),
   g_h2("6. Errores comunes"),
   g_ul(["Promediar velocidades o tasas con la media aritmética.", "Calcular la media geométrica con ceros o negativos (no se define).", "Promediar porcentajes directamente cuando las bases son distintas.", "Creer que \"el promedio\" es una sola cosa: siempre conviene preguntarse qué se está promediando."])],
  [("¿Cuándo se usa la media geométrica?", "Para tasas de crecimiento, rendimientos y razones: magnitudes que se multiplican entre sí."),
   ("¿Cuándo se usa la media armónica?", "Para promediar velocidades en tramos de igual distancia y para precios o rendimientos por unidad."),
   ("¿Cuál es la mayor y cuál la menor de las medias?", "Para números positivos: armónica ≤ geométrica ≤ aritmética ≤ cuadrática."),
   ("¿Cómo se calcula la media geométrica con calculadora?", "Multiplicando todos los datos y sacando la raíz n-ésima, o con logaritmos: exp(promedio de los ln).")],
  [("/calculadoras/estadistica/calculadora-de-medias/", "Calculadora de medias"), ("/guias/como-calcular-desviacion-estandar/", "Guía: desviación estándar"), ("/guias/como-calcular-promedio-de-notas/", "Guía: promedio de notas")])

# ============================================================ 6. errores
G("error-absoluto-relativo-y-porcentual", "Error absoluto, relativo y porcentual",
  "Error Absoluto, Relativo y Porcentual: Fórmulas, Incertidumbre y Ejemplos | Calculadora Científica",
  "Cómo calcular el error absoluto, relativo y porcentual de una medición, el error estándar de una serie de mediciones, la diferencia entre exactitud y precisión y ejemplos para informes de laboratorio.",
  "Errores de medición: fórmulas, incertidumbre y ejemplos resueltos.",
  "Error absoluto, relativo y porcentual",
  "Toda medición tiene un error. Saber cuánto vale y expresarlo bien es una parte central de cualquier informe de laboratorio, y se resuelve con tres fórmulas simples y una medida para series de datos.",
  "E = |medido − real| · e = E / |real| · e % = e × 100 · error estándar = s / √n.",
  ("/calculadoras/estadistica/calculadora-de-error-absoluto-y-relativo/", "Abrir calculadora"),
  [g_h2("1. Error absoluto, relativo y porcentual"),
   g_formula("E = |valor medido − valor real| &nbsp;&nbsp;·&nbsp;&nbsp; e = E / |valor real| &nbsp;&nbsp;·&nbsp;&nbsp; e % = e × 100"),
   g_ul(["El error absoluto tiene las unidades de la medición y dice cuánto se erró.", "El error relativo es un número sin unidades: permite comparar mediciones de distinta magnitud.", "El error porcentual es el relativo expresado en %."]),
   g_steps(["Se mide la aceleración de la gravedad y da 9,65 m/s² (valor de referencia: 9,81)", "E = |9,65 − 9,81| = 0,16 m/s²", "e = 0,16 / 9,81 = 0,0163 → 1,63 %"]),
   g_steps(["Se mide una pieza de 50 mm y la regla indica 49,2 mm", "E = 0,8 mm · e = 0,8 / 50 = 0,016 → 1,6 %"]),
   g_p("Un error de 1 cm es enorme si se mide un tornillo y despreciable si se mide una cancha: el relativo muestra la diferencia."),
   g_h2("2. Exactitud y precisión"),
   g_ul(["Exactitud: qué tan cerca está la medición del valor real (error pequeño).", "Precisión: qué tan parecidas son entre sí las mediciones repetidas (poca dispersión)."]),
   g_p("Una balanza mal calibrada puede dar siempre el mismo valor equivocado: es muy precisa pero poco exacta."),
   g_h2("3. Una serie de mediciones"),
   g_p("Cuando se repite la medición, el mejor valor es el promedio, y su incertidumbre se estima con el error estándar:"),
   g_formula("x̄ = Σx / n &nbsp;&nbsp;·&nbsp;&nbsp; s = √(Σ(x − x̄)² / (n − 1)) &nbsp;&nbsp;·&nbsp;&nbsp; error estándar = s / √n"),
   g_steps(["Cuatro mediciones de g: 9,80 · 9,70 · 9,90 · 9,75", "promedio = 9,7875", "s = 0,0854 · error estándar = 0,0854 / √4 = 0,0427", "resultado: g = 9,79 ± 0,04 m/s²"]),
   g_p("El error estándar baja con la raíz de la cantidad de mediciones: para reducirlo a la mitad hay que cuatro veces más datos."),
   g_h2("4. Cómo se expresa el resultado"),
   g_ul(["La incertidumbre se redondea a una o dos cifras significativas.", "El valor se escribe con los mismos decimales que la incertidumbre: 9,79 ± 0,04, no 9,7875 ± 0,04."]),
   g_h2("5. Propagación de errores (reglas simples)"),
   g_ul(["Suma y resta: se suman los errores absolutos.", "Producto y cociente: se suman los errores relativos."]),
   g_steps(["Un rectángulo mide 20,0 ± 0,1 cm por 10,0 ± 0,1 cm", "errores relativos: 0,1/20 = 0,5 % y 0,1/10 = 1 % → suma 1,5 %", "área = 200 cm² ± 1,5 % = 200 ± 3 cm²"]),
   g_h2("6. Errores comunes"),
   g_ul(["Dividir por el valor medido en lugar del valor real.", "Olvidar el valor absoluto y obtener un error negativo.", "Informar demasiados decimales.", "Confundir el desvío estándar (dispersión de los datos) con el error estándar (incertidumbre del promedio)."])],
  [("¿Cómo se calcula el error absoluto?", "Es el valor absoluto de la diferencia entre lo medido y el valor real."),
   ("¿Cómo se calcula el error porcentual?", "Se divide el error absoluto por el valor real y se multiplica por 100."),
   ("¿Qué diferencia hay entre exactitud y precisión?", "Exactitud: cercanía al valor real. Precisión: cercanía entre mediciones repetidas."),
   ("¿Qué es el error estándar de la media?", "s/√n: la incertidumbre del promedio de una serie de mediciones.")],
  [("/calculadoras/estadistica/calculadora-de-error-absoluto-y-relativo/", "Calculadora de errores de medición"), ("/guias/como-calcular-desviacion-estandar/", "Guía: desviación estándar"), ("/guias/intervalo-de-confianza-explicado/", "Guía: intervalo de confianza")])

# ============================================================ 7. propiedades coligativas
G("propiedades-coligativas-crioscopia-y-ebulloscopia", "Propiedades coligativas: crioscopía y ebulloscopía",
  "Propiedades Coligativas: Descenso Crioscópico y Ascenso Ebulloscópico (con Ejemplos) | Calculadora Científica",
  "Qué son las propiedades coligativas, cómo calcular el descenso del punto de congelación y el ascenso del punto de ebullición con ΔT = i·K·m, el factor de van't Hoff y ejemplos resueltos.",
  "Crioscopía y ebulloscopía: fórmulas, van't Hoff y ejemplos resueltos.",
  "Propiedades coligativas: crioscopía y ebulloscopía",
  "Por qué se echa sal a las calles heladas, por qué el agua con sal hierve un poco más caliente o por qué el anticongelante protege el motor: son propiedades coligativas, que dependen de cuántas partículas hay disueltas y no de cuáles son.",
  "ΔTf = i·Kf·m · ΔTb = i·Kb·m · m = moles de soluto / kg de solvente · agua: Kf = 1,86 y Kb = 0,512 °C·kg/mol.",
  ("/calculadoras/quimica/calculadora-de-propiedades-coligativas/", "Abrir calculadora"),
  [g_h2("1. Qué son"),
   g_p("Son las propiedades de una solución que dependen de la concentración de partículas de soluto y no de su naturaleza. Las cuatro son el descenso de la presión de vapor, el ascenso del punto de ebullición (ebulloscopía), el descenso del punto de congelación (crioscopía) y la presión osmótica."),
   g_h2("2. Las fórmulas"),
   g_formula("ΔTf = i · Kf · m &nbsp;&nbsp;·&nbsp;&nbsp; ΔTb = i · Kb · m"),
   g_ul(["m: molalidad, moles de soluto por kilogramo de solvente (mol/kg).", "Kf y Kb: constantes crioscópica y ebulloscópica, propias de cada solvente.", "i: factor de van't Hoff, la cantidad de partículas que genera cada unidad de soluto."]),
   g_table(["Solvente", "Kf (°C·kg/mol)", "Kb (°C·kg/mol)", "Congela a", "Hierve a"], [["Agua", "1,86", "0,512", "0 °C", "100 °C"], ["Benceno", "5,12", "2,53", "5,5 °C", "80,1 °C"], ["Etanol", "1,99", "1,22", "−114,1 °C", "78,4 °C"], ["Ácido acético", "3,90", "3,07", "16,6 °C", "118,1 °C"]]),
   g_h2("3. El factor de van't Hoff"),
   g_ul(["Azúcar y urea no se disocian: i = 1.", "NaCl se disocia en Na⁺ y Cl⁻: i ≈ 2.", "CaCl₂ se disocia en tres iones: i ≈ 3."]),
   g_p("Por eso un mol de sal baja el punto de congelación el doble que un mol de azúcar. En soluciones concentradas, i real es algo menor que el teórico."),
   g_h2("4. Ejemplo: sal en agua"),
   g_steps(["58,44 g de NaCl (1 mol) en 1 kg de agua: m = 1 mol/kg", "ΔTf = 2 · 1,86 · 1 = 3,72 °C → congela a −3,72 °C", "ΔTb = 2 · 0,512 · 1 = 1,024 °C → hierve a 101,02 °C"]),
   g_h2("5. Ejemplo: agua con sal para cocinar"),
   g_steps(["10 g de sal en 1 L (1 kg) de agua: 10 / 58,44 = 0,171 mol", "ΔTb = 2 · 0,512 · 0,171 ≈ 0,18 °C", "el agua hierve a unos 100,18 °C"]),
   g_p("Es una diferencia mínima: salar el agua no la hace hervir apreciablemente más caliente, aunque se diga lo contrario."),
   g_h2("6. Ejemplo: anticongelante"),
   g_steps(["620,7 g de etilenglicol (62,07 g/mol, i = 1) en 2 kg de agua", "moles = 10 → m = 10 / 2 = 5 mol/kg", "ΔTf = 1,86 · 5 = 9,3 °C → el agua congela a −9,3 °C"]),
   g_h2("7. Averiguar la masa molar de un soluto"),
   g_steps(["5 g de un soluto no iónico en 100 g de agua bajan el punto de congelación 0,93 °C", "m = ΔTf / Kf = 0,93 / 1,86 = 0,5 mol/kg", "moles = 0,5 × 0,1 kg = 0,05 mol → M = 5 g / 0,05 mol = 100 g/mol"]),
   g_h2("8. Límites y errores comunes"),
   g_ul(["Las fórmulas valen para soluciones diluidas e ideales; en las concentradas se aparta el resultado real.", "Usar la molaridad en lugar de la molalidad: hay que dividir por los kilogramos de solvente, no por los litros de solución.", "Olvidar el factor de van't Hoff en las sales.", "Pasar mal los gramos a kilogramos de solvente."])],
  [("¿Qué es el descenso crioscópico?", "La disminución del punto de congelación de un solvente al disolver un soluto: ΔTf = i·Kf·m."),
   ("¿Qué es el ascenso ebulloscópico?", "El aumento del punto de ebullición por un soluto no volátil: ΔTb = i·Kb·m."),
   ("¿Por qué se echa sal en las calles heladas?", "Porque la sal baja el punto de congelación del agua y derrite el hielo, hasta unos −21 °C."),
   ("¿Qué diferencia hay entre molalidad y molaridad?", "La molalidad son moles por kg de solvente; la molaridad, moles por litro de solución.")],
  [("/calculadoras/quimica/calculadora-de-propiedades-coligativas/", "Calculadora de propiedades coligativas"), ("/guias/como-calcular-molaridad/", "Guía: cómo calcular molaridad"), ("/guias/como-calcular-ppm-y-porcentaje-de-concentracion/", "Guía: ppm y porcentaje")])

# ============================================================ 8. pendiente de una rampa
G("como-calcular-la-pendiente-de-una-rampa", "Cómo calcular la pendiente de una rampa",
  "Cómo Calcular la Pendiente de una Rampa: Porcentaje, Grados y Largo Necesario | Calculadora Científica",
  "Cómo calcular la pendiente de una rampa en porcentaje y en grados, qué largo se necesita para salvar un desnivel, tabla de equivalencias y referencias de accesibilidad, con ejemplos resueltos.",
  "Pendiente en % y grados, largo necesario y accesibilidad de una rampa.",
  "Cómo calcular la pendiente de una rampa",
  "Una rampa muy empinada es incómoda y peligrosa; una muy larga ocupa demasiado espacio. Calcular la pendiente permite encontrar el equilibrio, sobre todo si debe ser accesible para sillas de ruedas o carritos.",
  "pendiente % = desnivel / longitud horizontal × 100 · ángulo = arctan(desnivel / longitud) · largo necesario = desnivel / (pendiente / 100).",
  ("/calculadoras/hogar-y-construccion/calculadora-de-pendiente-de-rampa/", "Abrir calculadora"),
  [g_h2("1. La pendiente en porcentaje"),
   g_formula("pendiente % = desnivel / longitud horizontal × 100"),
   g_p("El desnivel es la altura que se salva y la longitud horizontal es la proyección sobre el piso, no el largo de la superficie inclinada."),
   g_steps(["Una rampa sube 0,9 m en 9 m de largo horizontal", "pendiente = 0,9 / 9 × 100 = 10 %", "ángulo = arctan(0,1) ≈ 5,7°", "largo real de la rampa = √(9² + 0,9²) ≈ 9,04 m"]),
   g_p("Una pendiente del 10 % significa que se sube 10 cm por cada metro avanzado en horizontal."),
   g_h2("2. El largo necesario para una pendiente dada"),
   g_formula("longitud horizontal = desnivel / (pendiente / 100)"),
   g_steps(["Salvar un escalón de 50 cm con una pendiente del 8 %", "longitud = 0,5 / 0,08 = 6,25 m"]),
   g_h2("3. Equivalencias entre porcentaje y grados"),
   g_table(["Pendiente", "Ángulo", "Relación"], [["5 %", "2,9°", "1 : 20"], ["6 %", "3,4°", "1 : 16,7"], ["8 %", "4,6°", "1 : 12,5"], ["8,33 %", "4,8°", "1 : 12"], ["10 %", "5,7°", "1 : 10"], ["12 %", "6,8°", "1 : 8,3"], ["15 %", "8,5°", "1 : 6,7"], ["20 %", "11,3°", "1 : 5"], ["100 %", "45°", "1 : 1"]]),
   g_p("Los porcentajes y los grados no son proporcionales: una pendiente del 100 % es de 45°, no de 90°."),
   g_h2("4. Rampas accesibles"),
   g_p("Las normas de accesibilidad fijan pendientes máximas para que una persona en silla de ruedas pueda subir sin esfuerzo excesivo. La referencia internacional más difundida es 1:12 (8,33 %); en muchos reglamentos, el máximo va de alrededor del 6 % al 12 % según el largo del tramo, y se exigen descansos, pasamanos, un ancho mínimo y superficies antideslizantes."),
   g_ul(["Menos del 5 %: suave, cómoda para casi todos.", "Hasta 8 %: moderada, límite habitual en tramos largos.", "Hasta 12 %: pronunciada, solo en tramos cortos.", "Más del 12 %: no apta para sillas de ruedas ni carritos."]),
   g_p("Cada zona tiene su normativa de accesibilidad y de edificación: consultala antes de construir."),
   g_h2("5. Ejemplo: un escalón de entrada"),
   g_steps(["Escalón de 18 cm y 1,5 m de espacio disponible", "pendiente = 18 / 150 × 100 = 12 %", "es pronunciada: para llegar al 8 % harían falta 18 / 0,08 = 225 cm (2,25 m)"]),
   g_h2("6. Errores comunes"),
   g_ul(["Usar el largo de la superficie inclinada en lugar de la longitud horizontal.", "Mezclar centímetros y metros.", "Confundir porcentaje con grados.", "Olvidar los descansos y el ancho cuando la rampa es larga."])],
  [("¿Cómo se calcula la pendiente de una rampa?", "Dividiendo el desnivel por la longitud horizontal y multiplicando por 100."),
   ("¿Qué largo necesita una rampa para salvar 50 cm?", "Con una pendiente del 8 %, 6,25 m de longitud horizontal."),
   ("¿Cómo paso de porcentaje a grados?", "Con la arcotangente: un 10 % son 5,7°."),
   ("¿Cuál es la pendiente máxima de una rampa accesible?", "Depende de la norma local; la referencia internacional es 1:12 (8,33 %).")],
  [("/calculadoras/hogar-y-construccion/calculadora-de-pendiente-de-rampa/", "Calculadora de pendiente de rampa"), ("/guias/como-calcular-una-escalera/", "Guía: cómo calcular una escalera"), ("/guias/como-calcular-la-pendiente-y-la-distancia-entre-dos-puntos/", "Guía: pendiente entre dos puntos")])
